package techguns.registry;

import net.minecraft.core.Registry;
import net.minecraft.resources.ResourceKey;
import net.neoforged.neoforge.registries.DataPackRegistryEvent;
import techguns.TGIds;
import techguns.camo.TGCamo;

/**
 * Datapack registry of item camos ({@code data/<namespace>/techguns/camo/*.json}), synced to clients so they can pick
 * the texture. Entries are generated by {@code TGCamoProvider}; packs can add more (with textures in a resource pack).
 */
public final class TGCamos {
    public static final ResourceKey<Registry<TGCamo>> KEY = ResourceKey.createRegistryKey(TGIds.id("camo"));

    private TGCamos() {
    }

    // MIGRATION(26.x): datapack registry API; on 26.x camos can map onto equippable asset ids and item model `select`.
    static void register(DataPackRegistryEvent.NewRegistry event) {
        event.dataPackRegistry(KEY, TGCamo.CODEC, TGCamo.CODEC);
    }
}
